-- height gives an EXPLICIT rank ordering: derive() enforces Classic's rule that a
-- containing taxon's rank is strictly higher, and relying on id order breaks once
-- 'unranked clade'/'unranked' sit at the end. NULL height = unranked (no
-- comparison possible). See docs/classic-taxa-opinions.md §10.6 (D11) and the
-- DICTIONARIES header in the taxa/opinions section below. 'order' was previously
-- missing entirely (the list jumped suborder → superorder).
CREATE TABLE dictionaries.taxonomy_ranks (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    taxonomy_rank text NOT NULL,
    height integer
    );
INSERT INTO dictionaries.taxonomy_ranks (taxonomy_rank, height)
    VALUES ('subspecies', 10), ('species', 20), ('subgenus', 30), ('genus', 40),
           ('subtribe', 50), ('tribe', 60), ('subfamily', 70), ('family', 80),
           ('superfamily', 90), ('infraorder', 100), ('suborder', 110), ('order', 120),
           ('superorder', 130), ('infraclass', 140), ('subclass', 150), ('class', 160),
           ('superclass', 170), ('subphylum', 180), ('phylum', 190), ('superphylum', 200),
           ('subkingdom', 210), ('kingdom', 220), ('superkingdom', 230),
           ('unranked clade', NULL), ('unranked', NULL);

