-- namechange_reasons covers legacy `spelling_reason` ∪ the synonymy half of legacy
-- `status` ∪ the fold-shaped half of legacy nomenclatural-status opinions, reconciled
-- to eleven tokens (§10.6 D7; extended by the concept-fold decision, mapping doc §5.2,
-- 2026-08-18; extended again by the historical-misspelling split, migration_exploration
-- pair-24 discussion, 2026-08-19). edge_class ('root' | 'name' | 'concept') tells
-- derive() which of its two union-finds a name_opinions edge feeds; it is denormalized
-- onto each opinion row and FK-pinned to the composite key (id, edge_class) below, so
-- name_opinions' minting-shape rule can be a plain CHECK (Way 2 / A1 / §10.6 D9). 'root'
-- (not NULL) is 'original' — a lineage root with no target; a NULLable composite-FK
-- column could not be enforced. never_accepted marks reasons whose subject can never be
-- a lineage's accepted spelling (a misspelling is folded in for lookup only); derive()
-- step 3 excludes these.
--   * 'code' dropped: redundant with 'correction' (legacy routes code/grammar changes
--     through spelling_reason 'correction'); had no legacy source.
--   * 'misspelling' vs 'historical misspelling' — Classic distinguishes two provenances
--     for a misspelling claim that our model previously collapsed into one token.
--     'misspelling' is the curatorial case: a data enterer notices, while entering an
--     opinion about something else (any status, `spelling_reason = 'misspelling'`),
--     that the current reference happened to render the name incorrectly — no reference
--     is independently arguing the point. 'historical misspelling' is the dedicated
--     case: legacy `status = 'misspelling of'`, where the ENTIRE opinion, backed by its
--     own reference/evidence, is a formally published claim that a name is a
--     misspelling (the PBDB user guide's own term for this case). Checked against live
--     data (2026-08-19): `evidence` does not reliably distinguish the two (43.9% of
--     'misspelling of' rows are `stated with evidence` vs. 28.9% of `spelling_reason =
--     'misspelling'` rows — a skew, not a clean separator), so the distinction needed
--     its own token rather than being inferable from existing columns. Both tokens are
--     'name'-class and never_accepted, differing only in how the claim originated.
--   * 'invalid subgroup' and 'nomen oblitum' are concept-class folds, not synonymy in
--     the ordinary sense — Classic's own getSeniorSynonym/getMostRecentClassification
--     (classic/lib/PBDB/TaxonInfo.pm) fold both into the same senior-synonym chase as
--     'junior synonym'/'replaced by', by explicit comment ("technically not a synonym,
--     but treated computationally the same"). 'nomen oblitum' in particular reverses
--     nomenclatural priority (the chronologically senior name defers to the junior,
--     protected one) — the reversal needs no special derive() logic, since seniority is
--     already decided by which way concept edges point (subject defers to target), not
--     by comparing dates. The rest of the nomen family (nomen dubium, nomen nudum,
--     nomen vanum, and nomen oblitum when untargeted) stays in
--     dictionaries.nomenclatural_statuses — see that table's header and mapping doc §5.2
--     for the full per-token rationale.
--   * subjective/objective synonym split is carried by name_opinions.objective, not
--     by dictionary tokens; both legacy statuses map to 'junior synonym'. The same
--     column stays NULL for 'replaced by', 'invalid subgroup', and 'nomen oblitum'.
CREATE TABLE dictionaries.namechange_reasons (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    reason text NOT NULL,
    description text,
    edge_class text NOT NULL,
    never_accepted boolean NOT NULL DEFAULT false,
    CONSTRAINT namechange_reasons_edge_class_check CHECK (edge_class IN ('root', 'name', 'concept')),
    -- composite unique key referenced by name_opinions' (reason_id, edge_class) FK:
    CONSTRAINT namechange_reasons_id_edge_class_key UNIQUE (id, edge_class)
);
INSERT INTO dictionaries.namechange_reasons (reason, description, edge_class, never_accepted)
    VALUES
        ('original',         'The original published name',                                        'root',    false),
        ('correction',       'Grammatical/orthographic correction (incl. ICZN-code-mandated changes)', 'name',    false),
        ('reranked',         'The taxon has changed rank (from genus to family, implies re-assignment)', 'name',    false),
        ('recombination',    'Species combined with a different genus',                            'name',    false),
        ('assignment',       'The assignment of the taxon changed (e.g., new genus for species)',  'name',    false),
        ('misspelling',      'The taxon''s name was misspelled (noticed incidentally, e.g. while entering a belongs-to opinion; legacy spelling_reason=''misspelling'')', 'name',    true),
        ('historical misspelling', 'A formally published opinion whose entire content is the claim that this name is a misspelling (legacy status=''misspelling of'')', 'name',    true),
        ('junior synonym',   'The taxon is a junior synonym of another taxon',                     'concept', false),
        ('replaced by',      'Name replaced (e.g. homonymy)',                                      'concept', false),
        ('invalid subgroup', 'The taxon is an invalid subgroup, folded into the target''s concept', 'concept', false),
        ('nomen oblitum',    'A forgotten senior name, folded into the protected junior name''s concept', 'concept', false);

-- Sources taxa.nomenclatural_status_id — the residue of legacy nomenclatural-status
-- opinions that stays *self-referential testimony*, never a concept fold (mapping doc
-- §5.2, 2026-08-18). Two of the four tokens (invalid subgroup of, and nomen oblitum
-- when targeted) moved to namechange_reasons above; see that table's header. What's
-- left here splits into two kinds, per bars_candidacy:
--   * nomen dubium, nomen vanum: doubt about a name's quality/diagnosability, NOT an
--     act of invalidation. Recorded for the record; NEVER consulted by derive() (not
--     even the winning-opinion computation) — a deliberate pbdb2 departure from
--     Classic, which cannot distinguish doubt from invalidation because both compete
--     in the same reliability-ranked pool (TaxonInfo.pm getMostRecentClassification).
--   * nomen nudum: an explicit rejection of the name's availability. derive() computes
--     the winning validity opinion per subject permid (evidence/pubyr/id, same
--     discipline as everywhere else) and, if it is nomen nudum, excludes that permid
--     from its own lineage's accepted-spelling contest (bars_candidacy = true) — the
--     candidacy-bar mechanism, symmetric with never_accepted on name edges.
--   * nomen oblitum (untargeted only, no recorded protectum): treated the same as
--     nomen dubium/vanum — recorded testimony, no derive() effect. The targeted case
--     is a concept fold (see namechange_reasons); an untargeted "forgotten name" with
--     nothing to point at doesn't fit that shape and isn't required to bar candidacy.
-- target_permid was dropped entirely (was present on ~90% of legacy rows across this
-- whole family, including invalid subgroup of): once a row is here, its target (if the
-- legacy opinion had one) is never consumed by derive() by design, so there is nothing
-- to enforce a shape CHECK over — see mapping doc §5.2 for the live-data counts and the
-- accepted-loss rationale (nomen dubium: 7,245/8,208 targets dropped; nomen vanum:
-- 469/569; nomen nudum: 2,430/2,533; nomen oblitum untargeted-residue: 17/76 had none
-- to begin with).
CREATE TABLE dictionaries.nomenclatural_statuses (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    status text NOT NULL,
    bars_candidacy boolean NOT NULL DEFAULT false  -- true only for nomen nudum
);
INSERT INTO dictionaries.nomenclatural_statuses (status, bars_candidacy) VALUES
    ('nomen dubium',  false),
    ('nomen nudum',   true),
    ('nomen vanum',   false),
    ('nomen oblitum', false);


